#requires -Version 5.1

[CmdletBinding()]param()
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'RendererCompatibility.Common.ps1')

$script:PositiveCases=0;$script:NegativeCases=0
function Pass([string]$Name){$script:PositiveCases++;"PASS positive: $Name"}
function Pass-Negative([string]$Name){$script:NegativeCases++;"PASS negative: $Name"}
function New-TestSha([string]$Text){Get-HumanDesignReviewSha256ForText -Text $Text}
function Write-TestJson($Value,[string]$Path){[IO.File]::WriteAllText($Path,($Value|ConvertTo-Json -Depth 80),(New-Object Text.UTF8Encoding($false)))}
function Copy-TestValue($Value){$json=$Value|ConvertTo-Json -Depth 80;if($PSVersionTable.PSVersion.Major-ge7){$json|ConvertFrom-Json -DateKind String}else{$json|ConvertFrom-Json}}
function New-TestPng([string]$Path,[int]$Width,[int]$Height){$stride=$Width*4;$pixels=New-Object byte[] ($stride*$Height);for($i=0;$i-lt$pixels.Length;$i+=4){$pixels[$i]=20;$pixels[$i+1]=40;$pixels[$i+2]=60;$pixels[$i+3]=255};$bitmap=New-Object Windows.Media.Imaging.WriteableBitmap($Width,$Height,96,96,[Windows.Media.PixelFormats]::Bgra32,$null);$bitmap.WritePixels((New-Object Windows.Int32Rect(0,0,$Width,$Height)),$pixels,$stride,0);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bitmap));$stream=[IO.File]::Open($Path,[IO.FileMode]::Create,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$encoder.Save($stream)}finally{$stream.Dispose()}}
function New-TestPixelPng([string]$Path,[int]$Delta,[int]$Base=20,[switch]$Mask,[switch]$FullFrame,[switch]$Block){$width=4;$height=4;$stride=$width*4;$pixels=New-Object byte[] ($stride*$height);for($p=0;$p-lt$width*$height;$p++){$offset=$p*4;if($Mask){$selected=$FullFrame-or$p-eq5-or($Block-and$p-in@(6,9,10));$value=if($selected){255}else{0};$pixels[$offset]=$value;$pixels[$offset+1]=$value;$pixels[$offset+2]=$value;$pixels[$offset+3]=$value}else{$pixels[$offset]=[byte]($Base+$Delta*($p-eq5));$pixels[$offset+1]=40;$pixels[$offset+2]=60;$pixels[$offset+3]=255}};$bitmap=New-Object Windows.Media.Imaging.WriteableBitmap($width,$height,96,96,[Windows.Media.PixelFormats]::Bgra32,$null);$bitmap.WritePixels((New-Object Windows.Int32Rect(0,0,$width,$height)),$pixels,$stride,0);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bitmap));$stream=[IO.File]::Open($Path,[IO.FileMode]::Create,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$encoder.Save($stream)}finally{$stream.Dispose()}}
function New-FileBinding([string]$Root,[string]$Relative,[byte[]]$Bytes){$path=Join-Path $Root $Relative;$parent=Split-Path -Parent $path;if(-not(Test-Path $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};[IO.File]::WriteAllBytes($path,$Bytes);[ordered]@{relativePath=$Relative;bytes=[long]$Bytes.Length;sha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash}}
function New-EvidenceBinding([string]$Root,[string]$Relative,$Value,[string]$RepositoryRoot){$path=Join-Path $Root $Relative;$parent=Split-Path -Parent $path;if(-not(Test-Path $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};Write-RendererPackageCanonicalJson $Value $path $RepositoryRoot;$stable=Get-RendererPackageStableIdentity $path;$canonical=ConvertTo-RendererCanonicalJson $Value $RepositoryRoot;[ordered]@{relativePath=$Relative;bytes=[long]$stable.Length;fileSha256=$stable.Sha256;canonicalSha256=(New-TestSha $canonical)}}
function New-MatrixCases([string[]]$Ids){@($Ids|ForEach-Object{[ordered]@{id=$_;status='NOT_OBSERVED';evidenceReceipt=$null;notes=$null}})}
